import zipfile, re
from xml.etree import ElementTree as ET

z = zipfile.ZipFile("2026 首届 openvela AI 硬件开发者大赛 - 作品提交模板.docx")
xml = z.read("word/document.xml").decode("utf-8")

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
root = ET.fromstring(xml)

body = root.find('w:body', ns)

def para_text(p):
    texts = []
    for t in p.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}t'):
        texts.append(t.text or '')
    return ''.join(texts)

def is_heading(p):
    for pPr in p.iter('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}pStyle'):
        val = pPr.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val')
        if val and ('Heading' in val or 'heading' in val):
            return val
    return None

for child in body:
    tag = child.tag.split('}')[-1]
    if tag == 'p':
        txt = para_text(child)
        h = is_heading(child)
        if txt.strip():
            print(f"[{'H:'+h if h else 'P'}] {txt}")
    elif tag == 'tbl':
        print("  --- TABLE ---")
        for row in child.findall('w:tr', ns):
            cells = []
            for tc in row.findall('w:tc', ns):
                ct = []
                for p in tc.findall('w:p', ns):
                    ct.append(para_text(p))
                cells.append(' | '.join(ct).strip())
            print("   ROW:", ' || '.join(cells))
        print("  --- END TABLE ---")
